<template>
  <div class="workflow-page"><header class="heading"><div><h1>流程设计</h1><p>从设备实例或已有流程拖入画布，再配置节点能力和节点连接</p></div><div><el-select v-model="form.id" clearable placeholder="打开已有流程" class="open-flow" @change="id => id && loadWorkflow(id)"><el-option v-for="item in workflows" :key="item.id" :label="item.flowName" :value="item.id"/></el-select><el-button :icon="Refresh" @click="loadAll">刷新资源</el-button><el-button type="primary" :icon="Plus" @click="create">新建流程</el-button><el-button type="success" :loading="saving" @click="save">保存模型</el-button></div></header>
    <el-container class="designer"><el-aside width="290px" class="resource-panel"><div class="palette"><span>功能节点</span><button v-for="item in palette" :key="item.type" draggable="true" @dragstart="drag($event,{kind:'function',type:item.type})">{{ item.label }}</button></div><el-tabs v-model="tab" stretch><el-tab-pane label="设备列表" name="devices"><el-tree :data="deviceTree" node-key="key" default-expand-all :expand-on-click-node="false"><template #default="{data}"><div class="tree-item" :class="{draggable:data.kind==='instance'}" :draggable="data.kind==='instance'" @dragstart="drag($event,data)"><span>{{ data.label }}</span><small v-if="data.kind==='instance'">设备实例</small></div></template></el-tree><el-empty v-if="!deviceTree.length" description="暂无设备资源" :image-size="48"/></el-tab-pane><el-tab-pane label="流程列表" name="workflows"><div v-for="item in workflows.filter(x=>x.id!==form.id)" :key="item.id" class="flow-item" draggable="true" @dragstart="drag($event,{kind:'workflow',workflow:item})"><strong>{{ item.flowName }}</strong><span>{{ item.description || '拖入后创建子流程节点' }}</span></div><el-empty v-if="!workflows.filter(x=>x.id!==form.id).length" description="暂无可引用流程" :image-size="48"/></el-tab-pane></el-tabs></el-aside>
      <el-main class="main"><el-card shadow="never" class="meta"><el-form label-width="78px"><el-row :gutter="12"><el-col :span="10"><el-form-item label="流程名称"><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="4"><el-form-item label="版本"><el-input-number v-model="form.version" :min="1" :precision="0"/></el-form-item></el-col><el-col :span="5"><el-form-item label="状态"><el-select v-model="form.status"><el-option label="DRAFT" value="DRAFT"/><el-option label="ACTIVE" value="ACTIVE"/></el-select></el-form-item></el-col></el-row><el-form-item label="模型描述"><el-input v-model="form.description" type="textarea" :rows="2"/></el-form-item></el-form></el-card>
        <section class="canvas-wrap"><div class="canvas-head"><strong>流程画布</strong><span>拖入设备实例、子流程或功能节点。设备节点会自动建立STATE接口与该设备实例的双向连接</span></div><div class="canvas" @dragover.prevent @drop="drop"><el-empty v-if="!form.nodesDef.length" description="从左侧拖入节点开始设计流程" :image-size="64"/><article v-for="(node,index) in form.nodesDef" :key="node.name" :class="['node',{selected:selected===index}]" @click="selected=index"><header><strong>{{ node.name }}</strong><el-button link type="danger" @click.stop="removeNode(index)">删除</el-button></header><span>{{ label(node) }}</span><small>{{ interfaceSummary(node) }}</small></article></div></section>
        <el-card v-if="selectedNode" shadow="never" class="config"><template #header>节点配置：{{ selectedNode.name }}</template><el-form label-width="100px"><el-form-item label="节点名称"><el-input v-model="selectedNode.name" @focus="selectedNode._oldName=selectedNode.name" @change="renameNode"/></el-form-item><template v-if="selectedNode.nodeType==='DEV_NODE'"><el-form-item label="设备实例"><el-input :model-value="deviceName(selectedNode._deviceInstanceId)" disabled/></el-form-item><el-form-item label="设备模型"><el-input :model-value="modelName(selectedNode.deviceModelId)" disabled/></el-form-item><el-form-item label="设备能力"><el-select v-model="selectedNode.capability.capabilityName" filterable><el-option v-for="item in capabilities(selectedNode.deviceModelId)" :key="item.capabilityName" :label="item.capabilityName" :value="item.capabilityName"/></el-select></el-form-item></template><template v-else-if="selectedNode.nodeType==='SUBFLOW_NODE'"><el-form-item label="子流程"><el-input :model-value="workflowName(selectedNode.subFlowModelId)" disabled/></el-form-item><el-form-item label="说明"><el-input v-model="selectedNode.subFlowModelDescription"/></el-form-item></template><template v-else-if="selectedNode.functionType==='BRANCH'"><el-form-item label="分支表达式"><el-input v-model="selectedNode.expression" placeholder="引用本节点internalVariables"/></el-form-item></template></el-form></el-card>
        <el-row :gutter="14" class="connections"><el-col :span="12"><el-card shadow="never"><template #header><div class="card-head">节点连接<el-button type="primary" plain size="small" @click="connectionVisible=true">添加连接</el-button></div></template><el-table :data="nodeConnections" size="small" border><el-table-column label="源节点"><template #default="{row}">{{ row.source.nodeName }}.{{ row.source.interfaceName }}</template></el-table-column><el-table-column label="目标节点"><template #default="{row}">{{ row.target.nodeName }}.{{ row.target.interfaceName }}</template></el-table-column><el-table-column width="55"><template #default="{$index}"><el-button link type="danger" @click="removeConnection($index)">删除</el-button></template></el-table-column></el-table></el-card></el-col><el-col :span="12"><el-card shadow="never"><template #header>设备接口连接</template><el-table :data="deviceConnections" size="small" border><el-table-column prop="connectionType" label="类型" width="118"/><el-table-column label="连接"><template #default="{row}">{{ endpoint(row.source) }} → {{ endpoint(row.target) }}</template></el-table-column></el-table></el-card></el-col></el-row>
      </el-main></el-container>
    <el-dialog v-model="connectionVisible" title="添加节点连接" width="600px"><el-form :model="connection" label-width="86px"><el-form-item label="源节点"><el-select v-model="connection.sourceNode" @change="connection.sourceInterface=''"><el-option v-for="node in form.nodesDef" :key="node.name" :label="node.name" :value="node.name"/></el-select></el-form-item><el-form-item label="源接口"><el-select v-model="connection.sourceInterface"><el-option v-for="item in outputInterfaces(connection.sourceNode)" :key="item.name" :label="item.name" :value="item.name"/></el-select></el-form-item><el-form-item label="目标节点"><el-select v-model="connection.targetNode" @change="connection.targetInterface=''"><el-option v-for="node in form.nodesDef" :key="node.name" :label="node.name" :value="node.name"/></el-select></el-form-item><el-form-item label="目标接口"><el-select v-model="connection.targetInterface"><el-option v-for="item in inputInterfaces(connection.targetNode)" :key="item.name" :label="item.name" :value="item.name"/></el-select></el-form-item></el-form><template #footer><el-button @click="connectionVisible=false">取消</el-button><el-button type="primary" @click="addConnection">确认</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import axios from 'axios'
import { ElMessage,ElMessageBox } from 'element-plus'
import { Plus,Refresh } from '@element-plus/icons-vue'
type Node=Record<string,any>;const tab=ref('devices'),workflows=ref<any[]>([]),models=ref<any[]>([]),instances=ref<any[]>([]),categories=ref<any[]>([]),saving=ref(false),selected=ref<number|null>(null),connectionVisible=ref(false),connection=reactive({sourceNode:'',sourceInterface:'',targetNode:'',targetInterface:''})
const empty=()=>({id:null as number|null,name:'',description:'',version:1,status:'DRAFT',nodesDef:[] as Node[],interfaceConnections:[] as any[],portConnections:[] as any[]}),form=reactive<any>(empty()),palette=[{type:'START',label:'START'},{type:'END',label:'END'},{type:'BRANCH',label:'分支'},{type:'AGGREGATE',label:'汇聚'}],selectedNode=computed(()=>selected.value===null?null:form.nodesDef[selected.value]),nodeConnections=computed(()=>form.interfaceConnections.filter((x:any)=>x.connectionType==='NODE_TO_NODE')),deviceConnections=computed(()=>form.interfaceConnections.filter((x:any)=>x.connectionType!=='NODE_TO_NODE'))
const deviceTree=computed(()=>{const map=new Map<any,any>();categories.value.forEach((c:any)=>map.set(c.id||c.categoryId,{key:'c-'+(c.id||c.categoryId),kind:'category',label:c.categoryName||c.name,children:[]}));const roots:any[]=[];map.forEach((item:any)=>{const raw=categories.value.find((x:any)=>'c-'+(x.id||x.categoryId)===item.key);const parent=map.get(raw?.parentCategoryId);(parent?parent.children:roots).push(item)});models.value.forEach((model:any)=>{const category=map.get(model.categoryId);const parent=category?category.children:roots;const modelNode={key:'m-'+model.id,kind:'model',label:model.modelName,children:instances.value.filter((x:any)=>Number(x.deviceModelId||x.modelId)===Number(model.id)).map((x:any)=>({key:'i-'+x.id,kind:'instance',label:x.instanceName||('设备'+x.id),instance:x,model}))};parent.push(modelNode)});return roots})
function reset(value:any){Object.assign(form,empty(),value,{nodesDef:value.nodesDef||[],interfaceConnections:value.interfaceConnections||[],portConnections:value.portConnections||[]});selected.value=null}function create(){reset(empty())}function name(prefix:string){let i=1;while(form.nodesDef.some((x:any)=>x.name===prefix+i))i++;return prefix+i}function lifecycle(){return{initialStateName:'PENDING',states:['PENDING','RUNNING','SUCCEEDED','FAILED','TERMINATING','TERMINATED'],transitions:[{fromStateName:'PENDING',toStateName:'RUNNING'},{fromStateName:'PENDING',toStateName:'TERMINATED'},{fromStateName:'RUNNING',toStateName:'SUCCEEDED'},{fromStateName:'RUNNING',toStateName:'FAILED'},{fromStateName:'RUNNING',toStateName:'TERMINATING'},{fromStateName:'TERMINATING',toStateName:'TERMINATED'},{fromStateName:'TERMINATING',toStateName:'FAILED'}]}}function inPort(action?:string){const x:any={name:'Interface_workflow_in',direction:'IN',interfaceType:'WORKFLOW',allowedSignals:['ACTIVE']};if(action)x.bindingTriggers=[{condition:{object:'inputSignalName',operator:'=',threshold:'ACTIVE'},action}];return x}function outPort(){return{name:'Interface_workflow_out',direction:'OUT',interfaceType:'WORKFLOW',allowedSignals:['ACTIVE']}}
function standard(type:string,data?:any):Node{if(type==='START')return{name:name('start'),nodeType:'FUNC_NODE',functionType:'START',internalVariables:[],interfaces:[outPort()],ports:[],actions:[{actionName:'emitActive',actionType:'EMIT',targetInterfaceName:'Interface_workflow_out',signalName:'ACTIVE'}]};if(type==='END')return{name:name('end'),nodeType:'FUNC_NODE',functionType:'END',internalVariables:[],interfaces:[inPort()],ports:[],actions:[]};if(type==='SUBFLOW_NODE')return{name:name('subflow'),nodeType:'SUBFLOW_NODE',subFlowModelId:data.id,subFlowModelDescription:data.description||'',internalVariables:[],lifecycle:lifecycle(),interfaces:[inPort(),outPort()],ports:[],actions:[]};if(type==='DEV_NODE')return{name:name('device'),nodeType:'DEV_NODE',deviceModelId:data.model.id,capability:{capabilityName:'',capabilityParameters:{}},_deviceInstanceId:data.instance.id,internalVariables:[],lifecycle:lifecycle(),interfaces:[inPort('startDevice'),{name:'Interface_state_out',direction:'OUT',interfaceType:'STATE',allowedSignals:['WF_EXECUTE_START']},{name:'Interface_state_in',direction:'IN',interfaceType:'STATE',allowedSignals:['CMD_STATE','OP_STATE'],bindingTriggers:[{condition:{object:'inputPayload.stateName',operator:'=',threshold:'COMPLETED'},action:'completeNode'}]},outPort()],ports:[],actions:[{actionName:'startDevice',actionType:'EMIT',targetInterfaceName:'Interface_state_out',signalName:'WF_EXECUTE_START'},{actionName:'completeNode',actionType:'EMIT',targetInterfaceName:'Interface_workflow_out',signalName:'ACTIVE'}]};return{name:name(type==='BRANCH'?'branch':'aggregate'),nodeType:'FUNC_NODE',functionType:type,expression:type==='BRANCH'?'true':'',internalVariables:[],interfaces:[inPort('emitActive'),outPort()],ports:[],actions:[{actionName:'emitActive',actionType:'EMIT',targetInterfaceName:'Interface_workflow_out',signalName:'ACTIVE'}]}}
function drag(event:DragEvent,data:any){event.dataTransfer?.setData('workflow-resource',JSON.stringify(data));if(event.dataTransfer)event.dataTransfer.effectAllowed='copy'}function drop(event:DragEvent){try{const data=JSON.parse(event.dataTransfer?.getData('workflow-resource')||'{}');let node:Node;if(data.kind==='instance')node=standard('DEV_NODE',data);else if(data.kind==='workflow')node=standard('SUBFLOW_NODE',data.workflow);else if(data.kind==='function')node=standard(data.type);else return;form.nodesDef.push(node);selected.value=form.nodesDef.length-1;if(node.nodeType==='DEV_NODE'){const id=node._deviceInstanceId;form.interfaceConnections.push({connectionType:'NODE_TO_DEVICE',source:{nodeName:node.name,interfaceName:'Interface_state_out'},target:{deviceInstanceId:id,interfaceName:'Interface_workflow_in'}},{connectionType:'DEVICE_TO_NODE',source:{deviceInstanceId:id,interfaceName:'Interface_state_out'},target:{nodeName:node.name,interfaceName:'Interface_state_in'}})}}catch{ElMessage.error('无法识别拖入的资源')}}
function label(node:any){if(node.nodeType==='DEV_NODE')return'设备能力：'+(node.capability?.capabilityName||'待选择');if(node.nodeType==='SUBFLOW_NODE')return'子流程：'+workflowName(node.subFlowModelId);return node.functionType}function interfaceSummary(node:any){return(node.interfaces||[]).map((x:any)=>x.name).join('、')}function modelName(id:any){return models.value.find((x:any)=>Number(x.id)===Number(id))?.modelName||String(id||'')}function deviceName(id:any){return instances.value.find((x:any)=>Number(x.id)===Number(id))?.instanceName||String(id||'')}function workflowName(id:any){return workflows.value.find((x:any)=>Number(x.id)===Number(id))?.flowName||String(id||'')}function capabilities(id:any){return models.value.find((x:any)=>Number(x.id)===Number(id))?.capabilities||[]}function endpoint(value:any){return value.nodeName?value.nodeName+'.'+value.interfaceName:'设备'+value.deviceInstanceId+'.'+value.interfaceName}function inputInterfaces(nodeName:string){return(form.nodesDef.find((x:any)=>x.name===nodeName)?.interfaces||[]).filter((x:any)=>x.direction==='IN'&&x.interfaceType==='WORKFLOW')}function outputInterfaces(nodeName:string){return(form.nodesDef.find((x:any)=>x.name===nodeName)?.interfaces||[]).filter((x:any)=>x.direction==='OUT'&&x.interfaceType==='WORKFLOW')}
function addConnection(){if(!connection.sourceNode||!connection.sourceInterface||!connection.targetNode||!connection.targetInterface)return ElMessage.error('请选择完整的节点接口');if(connection.sourceNode===connection.targetNode)return ElMessage.error('节点不能连接到自身');form.interfaceConnections.push({connectionType:'NODE_TO_NODE',source:{nodeName:connection.sourceNode,interfaceName:connection.sourceInterface},target:{nodeName:connection.targetNode,interfaceName:connection.targetInterface}});connectionVisible.value=false;Object.assign(connection,{sourceNode:'',sourceInterface:'',targetNode:'',targetInterface:''})}function removeConnection(index:number){const target=nodeConnections.value[index];const real=form.interfaceConnections.indexOf(target);if(real>=0)form.interfaceConnections.splice(real,1)}function renameNode(){const node=selectedNode.value;if(!node)return;const duplicate=form.nodesDef.some((x:any)=>x!==node&&x.name===node.name);if(duplicate){ElMessage.error('节点名称不能重复');return}form.interfaceConnections.forEach((x:any)=>{if(x.source?.nodeName===node._oldName)x.source.nodeName=node.name;if(x.target?.nodeName===node._oldName)x.target.nodeName=node.name});node._oldName=node.name}async function removeNode(index:number){const node=form.nodesDef[index];await ElMessageBox.confirm('删除节点及其全部连接？','确认删除',{type:'warning'});form.nodesDef.splice(index,1);form.interfaceConnections=form.interfaceConnections.filter((x:any)=>x.source?.nodeName!==node.name&&x.target?.nodeName!==node.name);selected.value=null}
async function loadList(){const res=await axios.get('/api/workflow/list');if(!res.data?.success)throw Error(res.data?.message||'加载失败');workflows.value=res.data.data||[]}async function loadAll(){try{const [m,i,c]=await Promise.all([axios.get('/api/device/model/list'),axios.get('/api/device/instance/list'),axios.get('/api/device/category/list')]);if(m.data?.success)models.value=m.data.data||[];if(i.data?.success)instances.value=i.data.data||[];if(c.data?.success)categories.value=c.data.data||[];await loadList()}catch(e:any){ElMessage.error(e.message||'加载设计资源失败')}}async function save(){if(!form.name.trim())return ElMessage.error('请输入流程名称');if(form.nodesDef.some((x:any)=>x.nodeType==='DEV_NODE'&&!x.capability?.capabilityName))return ElMessage.error('请为每个设备节点选择设备能力');saving.value=true;try{const payload=JSON.parse(JSON.stringify(form));payload.nodesDef.forEach((x:any)=>{delete x._deviceInstanceId;delete x._oldName});const res=await axios.post('/api/workflow/save',payload);if(!res.data?.success)throw Error(res.data?.message||'保存失败');form.id=res.data.data.workflowId;ElMessage.success('工作流模型已保存');await loadList()}catch(e:any){ElMessage.error(e.message||'保存失败')}finally{saving.value=false}}async function loadWorkflow(id:number){const res=await axios.get('/api/workflow/detail/'+id);if(!res.data?.success)throw Error(res.data?.message||'加载失败');reset(res.data.data)}onMounted(loadAll)
</script>
<style scoped>
.workflow-page{padding:20px}.heading,.heading>div:last-child,.palette,.card-head{display:flex;align-items:center;gap:10px}.heading{justify-content:space-between;margin-bottom:16px}.heading h1{margin:0;font-size:22px}.heading p{margin:6px 0 0;color:#64748b;font-size:13px}.open-flow{width:190px}.designer{min-height:calc(100vh - 145px);gap:14px}.resource-panel{padding:12px;border:1px solid #e2e8f0;border-radius:6px;background:#fff}.palette{flex-wrap:wrap;padding-bottom:12px;border-bottom:1px solid #e5e7eb}.palette span{width:100%;font-weight:600}.palette button{border:1px solid #bcd4f5;border-radius:4px;background:#f8fbff;padding:5px 8px;color:#2563eb;cursor:grab}.tree-item{display:flex;align-items:center;justify-content:space-between;width:100%}.tree-item.draggable,.flow-item{cursor:grab}.tree-item small,.flow-item span{color:#64748b;font-size:11px}.flow-item{display:grid;gap:4px;padding:10px;border-bottom:1px solid #eef2f7}.main{padding:0;min-width:0}.canvas-wrap{margin-top:14px;border:1px solid #dbe4ef;border-radius:6px;background:#fff}.canvas-head{padding:10px 12px;border-bottom:1px solid #e5e7eb}.canvas-head span{margin-left:10px;color:#64748b;font-size:12px}.canvas{min-height:340px;padding:16px;display:flex;flex-wrap:wrap;align-content:flex-start;gap:12px;background-image:radial-gradient(#dbe4ef 1px,transparent 1px);background-size:16px 16px}.node{width:190px;min-height:90px;padding:10px;border:1px solid #9cbce4;border-radius:6px;background:#fff;cursor:pointer;display:grid;gap:7px}.node.selected{border:2px solid #2563eb;box-shadow:0 0 0 2px #dbeafe}.node header{display:flex;justify-content:space-between}.node span{font-size:13px}.node small{color:#64748b;font-size:11px}.config,.connections{margin-top:14px}.card-head{justify-content:space-between}@media(max-width:1000px){.designer{display:block}.resource-panel{width:auto!important;margin-bottom:14px}}
</style>